     *   (`409 COMPANY_ACTIVE_IN_PRODUCTION`), one holding any invoice in Live — issued, draft
     *   or proforma (`409 COMPANY_HAS_INVOICES`) — and the account's primary NIF
     *   (`400 CANNOT_DELETE_PRIMARY`).
